const sSOSetSCIMToken = `-- name: SSOSetSCIMToken :execrows
INSERT INTO organization_sso(organization_id,scim_token_hash) VALUES($1,$2)
ON CONFLICT(organization_id) DO UPDATE SET scim_token_hash=excluded.scim_token_hash
`

type SSOSetSCIMTokenParams struct {
	OrganizationID int64  `json:"organization_id"`
	ScimTokenHash  string `json:"scim_token_hash"`
}

// SCIM provisioning works without SSO sign-in: the first rotation creates the
// (disabled) settings row.
func (q *Queries) SSOSetSCIMToken(ctx context.Context, arg SSOSetSCIMTokenParams) (int64, error) {
	result, err := q.db.Exec(ctx, sSOSetSCIMToken, arg.OrganizationID, arg.ScimTokenHash)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

